package com.xyz.question_bank_management_system.modules.profile.service.impl;
import com.xyz.question_bank_management_system.modules.profile.entity.StudentKnowledgeState;import com.xyz.question_bank_management_system.modules.profile.model.ValidatedInteraction;import org.junit.jupiter.api.Test;import java.math.BigDecimal;import java.util.Map;import static org.junit.jupiter.api.Assertions.*;
class KnowledgeStateServiceImplV1Test {@Test void appliesOnlyNewWeightedInteraction(){KnowledgeStateServiceImpl service=new KnowledgeStateServiceImpl();StudentKnowledgeState state=new StudentKnowledgeState();state.setKnowledgePointId(10L);state.setMasteryValue(new BigDecimal("0.3000"));state.setConfidence(BigDecimal.ZERO);state.setEvidenceCount(0);state.setAttemptCount(0);state.setCorrectCount(0);state.setStateVersion(0L);state.setLastInteractionSeq(0L);ValidatedInteraction i=new ValidatedInteraction();i.setId(9L);i.setInteractionSeq(1L);i.setScoreNormalized(BigDecimal.ONE);i.setQuestionDifficulty(new BigDecimal("0.5"));i.setQuestionPurpose("KNOWLEDGE_ASSESSMENT");i.setKnowledgeWeights(Map.of(10L,BigDecimal.ONE));StudentKnowledgeState next=service.update(state,java.util.List.of(i)).getStates().get(0);assertTrue(next.getMasteryValue().compareTo(state.getMasteryValue())>0);assertEquals(1,next.getEvidenceCount());assertEquals(1L,next.getLastInteractionSeq());assertEquals("WEIGHTED_BKT_ELO",next.getCalculationMethod());}}
